<?php
function page_verification():void {
 $suppliers=rows("SELECT s.*, (SELECT COUNT(*) FROM cooperatives c WHERE c.supplier_id=s.id AND c.status='verified') verified_coops, (SELECT COUNT(*) FROM cooperatives c WHERE c.supplier_id=s.id) all_coops FROM suppliers s ORDER BY FIELD(s.status,'pending','rejected','verified'),s.id DESC");
 $coops=rows('SELECT c.*,s.legal_name, r.name raw_name FROM cooperatives c JOIN suppliers s ON s.id=c.supplier_id JOIN raw_types r ON r.id=c.specialty_raw_type_id ORDER BY FIELD(c.status,\'pending\',\'rejected\',\'verified\'),c.id DESC');
 $buyers=rows('SELECT * FROM buyer_profiles ORDER BY FIELD(status,\'pending\',\'rejected\',\'verified\'),id DESC');
 ?><div class="notice mb-4"><strong>Aturan pendaftaran:</strong> PT dapat berstatus terverifikasi hanya setelah sedikitnya <strong>5 koperasi anak</strong> dalam jaringan PT tersebut disetujui Koperasi Induk. Verifikasi harus berdasarkan dokumen dan pemeriksaan nyata, bukan hanya nama yang diajukan.</div>
<div class="panel mb-4"><div class="panel-pad section-title mb-0"><h5>PT pemasok · <?=count($suppliers)?></h5></div><div class="table-responsive"><table class="table"><thead><tr><th>PT / NIB</th><th>Wilayah</th><th>Koperasi valid</th><th>Status</th><th>Keputusan</th></tr></thead><tbody><?php foreach($suppliers as $s):?><tr><td><strong><?=e($s['legal_name'])?></strong><div class="helper">NIB: <?=e($s['nib'])?></div></td><td><?=e($s['city'].', '.$s['province'])?></td><td><strong><?=e($s['verified_coops'])?></strong> / <?=e($s['all_coops'])?> <small>valid</small></td><td><?=badge($s['status'])?></td><td><div class="d-flex gap-1"><?php action_form('verify_supplier',(int)$s['id'],'Setujui','btn-outline-coco',['status'=>'verified']);action_form('verify_supplier',(int)$s['id'],'Tolak','btn-outline-danger',['status'=>'rejected']);?></div></td></tr><?php endforeach;?></tbody></table><?php if(!$suppliers)table_empty();?></div></div>
<div class="panel mb-4"><div class="panel-pad section-title mb-0"><h5>Koperasi anak · <?=count($coops)?></h5></div><div class="table-responsive"><table class="table"><thead><tr><th>Koperasi</th><th>Mitra PT</th><th>Fokus pengolahan</th><th>Wilayah</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($coops as $c):?><tr><td class="fw-bold"><?=e($c['name'])?></td><td><?=e($c['legal_name'])?></td><td><?=e($c['raw_name'])?></td><td><?=e($c['city'])?></td><td><?=badge($c['status'])?></td><td><?php action_form('verify_coop',(int)$c['id'],'Setujui','btn-outline-coco',['status'=>'verified']);?> <?php action_form('verify_coop',(int)$c['id'],'Tolak','btn-outline-danger',['status'=>'rejected']);?></td></tr><?php endforeach;?></tbody></table><?php if(!$coops)table_empty();?></div></div>
<div class="panel"><div class="panel-pad section-title mb-0"><h5>Calon pembeli industri · <?=count($buyers)?></h5></div><div class="table-responsive"><table class="table"><thead><tr><th>Perusahaan</th><th>Kota</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($buyers as $b):?><tr><td class="fw-bold"><?=e($b['company_name'])?></td><td><?=e($b['city'])?></td><td><?=badge($b['status'])?></td><td><?php action_form('verify_buyer',(int)$b['id'],'Setujui','btn-outline-coco',['status'=>'verified']);?> <?php action_form('verify_buyer',(int)$b['id'],'Tolak','btn-outline-danger',['status'=>'rejected']);?></td></tr><?php endforeach;?></tbody></table><?php if(!$buyers)table_empty();?></div></div>
<?php }
